<script setup lang="ts">
import { computed, onMounted, onBeforeUnmount, reactive, ref, watch, nextTick } from 'vue'
import { NConfigProvider, NButton, NInput, NInputNumber, NSelect, NSwitch, NModal, NForm, NFormItem, NCheckbox, NPopconfirm, NDropdown, NTag, NEmpty, NSpin } from 'naive-ui'
import { Cable, Radio, Braces, BookOpen, Settings2, Plus, Search, ChevronDown, ChevronRight, Play, Square, Save, Upload, Download, Trash2, FileCode2, Activity, Terminal, Clock3, ArrowUpRight, ArrowDownLeft, Copy, Check, Circle, X, Layers3, PlugZap } from '@lucide/vue'
import type { Service, Request, Workspace, State, Event, SessionState, Dictionary, CustomFunction } from './types'
import { api, uid, download } from './services/api'
import CodeEditor from './components/CodeEditor.vue'
import FixFields from './features/fix/FixFields.vue'
import { decodeFix } from './features/fix/decode'

const theme={common:{primaryColor:'#7956e8',primaryColorHover:'#8c6bef',primaryColorPressed:'#6543ce',borderRadius:'7px',fontFamily:'"Segoe UI", "Microsoft YaHei", sans-serif',fontSize:'13px'}}
const workspace=ref<Workspace>({version:1,services:[],requests:[],functions:[],dictionaries:[]})
const sessions=ref<Record<string,SessionState>>({}),events=ref<Event[]>([]),lastId=ref(0)
const page=ref('workbench'),selectedId=ref(''),serviceId=ref(''),openTabs=ref<string[]>([]),tab=ref('message'),bottomTab=ref('messages')
const search=ref(''),busy=ref(''),dirty=ref(false),loading=ref(true),optional=ref(false),preview=ref(''),previewError=ref(''),view=ref('text'),selectedEventId=ref<number|null>(null),serviceModal=ref(false)
const dictionaries=reactive<Record<string,Dictionary>>({}),functionKind=ref<'request'|'response'|'frame'>('request'),selectedFunction=ref(''),toast=ref(''),toastError=ref(false),expanded=reactive<Record<string,boolean>>({})
const importXML=ref<HTMLInputElement>(),importJSON=ref<HTMLInputElement>()
const requestModal=ref(false),requestServiceId=ref(''),requestMessageType=ref('')
const serviceFunctionEditor=ref(false)
const requestDictionary=computed(()=>dictionaries[workspace.value.services.find(s=>s.id===requestServiceId.value)?.dictionaryId||''])
let poll:number|undefined,toastTimer:ReturnType<typeof setTimeout>,previewTimer:ReturnType<typeof setTimeout>,polling=false,initializing=true,previewRevision=0
const current=computed(()=>workspace.value.requests.find(r=>r.id===selectedId.value))
const service=computed(()=>workspace.value.services.find(s=>s.id===(current.value?.serviceId||serviceId.value)))
const state=computed(()=>sessions.value[service.value?.id||''])
const dict=computed(()=>dictionaries[service.value?.dictionaryId||''])
const currentMessage=computed(()=>dict.value?.messages.find(m=>m.type===current.value?.messageType))
const searchQuery=computed(()=>search.value.trim().toLowerCase())
const filteredServices=computed(()=>workspace.value.services.map(s=>{
  const serviceMatches=s.name.toLowerCase().includes(searchQuery.value)
  const rows=requestsFor(s.id)
  const requests=!searchQuery.value||serviceMatches?rows:rows.filter(r=>r.name.toLowerCase().includes(searchQuery.value)||r.messageType?.toLowerCase().includes(searchQuery.value))
  return {service:s,requests,serviceMatches}
}).filter(item=>!searchQuery.value||item.serviceMatches||item.requests.length))
const serviceEvents=computed(()=>events.value.filter(e=>!service.value||e.serviceId===service.value.id))
const messages=computed(()=>serviceEvents.value.filter(e=>e.kind==='message'))
const logs=computed(()=>serviceEvents.value.filter(e=>e.kind!=='message'))
const selectedEvent=computed(()=>messages.value.find(e=>e.id===selectedEventId.value)||messages.value.at(-1))
const decoded=computed(()=>decodeFix(selectedEvent.value?.raw||'',dict.value))
const activeFunction=computed(()=>workspace.value.functions.find(f=>f.id===selectedFunction.value))
const functionOptions=(kind:string)=>[{label:'不处理',value:''},...workspace.value.functions.filter(f=>f.kind===kind).map(f=>({label:f.name,value:f.id}))]
const msgOptions=computed(()=>dict.value?.messages.map(m=>({label:`${m.type} · ${m.name}`,value:m.type}))||[])
const draft=reactive<Service>(newService('tcp'))
const frameFunctions=computed(()=>workspace.value.functions.filter(f=>f.kind==='frame'))
const framingOptions=computed(()=>[
  {type:'group' as const,label:'内置接收规则',key:'builtin',children:[{label:'每次收到数据即展示（不拆包）',value:'chunk'},{label:'包含分隔符',value:'delimiter'},{label:'固定报文字节数',value:'fixed'},{label:'ASCII 长度头 + 包体',value:'length'}]},
  ...(frameFunctions.value.length?[{type:'group' as const,label:'自定义接收完成判断函数',key:'functions',children:frameFunctions.value.map(f=>({label:f.name,value:'function:'+f.id}))}]:[])
])
const framingRule=computed({
  get:()=>draft.framing==='custom'?(draft.frameFunctionId?'function:'+draft.frameFunctionId:null):(draft.framing||'chunk'),
  set:(value:string|null)=>{if(!value)return;if(value.startsWith('function:')){draft.framing='custom';draft.frameFunctionId=value.slice(9)}else{draft.framing=value;draft.frameFunctionId=''}}
})
const boundFrameFunction=computed(()=>frameFunctions.value.find(f=>f.id===draft.frameFunctionId))
function manageFrameFunctions(){serviceModal.value=false;serviceFunctionEditor.value=true;page.value='functions';functionKind.value='frame';selectedFunction.value=draft.frameFunctionId||frameFunctions.value[0]?.id||''}
function returnToService(bind=false){if(bind&&activeFunction.value?.kind==='frame'){draft.framing='custom';draft.frameFunctionId=activeFunction.value.id};serviceFunctionEditor.value=false;page.value='workbench';serviceModal.value=true}
function newService(protocol:'tcp'|'fix'):Service{return {id:uid(),name:protocol==='fix'?'新建 FIX 服务':'新建 TCP 服务',protocol,host:'127.0.0.1',port:9878,timeoutMs:5000,dictionaryId:workspace.value?.dictionaries?.[0]?.id||'',framing:'chunk',delimiter:'\n',frameLength:8,frameFunctionId:'',sender:'FixClient',target:'Fix',heartbeat:30,autoLogon:false,resetOnLogon:true,username:'',password:''}}
function notify(text:string,error=false){toast.value=text;toastError.value=error;clearTimeout(toastTimer);toastTimer=setTimeout(()=>toast.value='',6000)}
async function action<T>(name:string,fn:()=>Promise<T>):Promise<T|undefined>{busy.value=name;try{return await fn()}catch(e){notify(String(e instanceof Error?e.message:e),true)}finally{busy.value=''}}
function requestsFor(id:string){return workspace.value.requests.filter(r=>r.serviceId===id)}
function openRequest(id:string){selectedId.value=id;const r=workspace.value.requests.find(r=>r.id===id);if(r){serviceId.value=r.serviceId;expanded[r.serviceId]=true};if(!openTabs.value.includes(id))openTabs.value.push(id);page.value='workbench';selectedEventId.value=null;nextTick(()=>document.querySelector('.tree-request-row.selected')?.scrollIntoView({block:'nearest'}))}
function closeTab(id:string){openTabs.value=openTabs.value.filter(x=>x!==id);if(selectedId.value===id){selectedId.value=openTabs.value.at(-1)||''}}
async function load(){const s=await api<State>('Snapshot',0);initializing=true;workspace.value=s.workspace;for(const name of ['services','requests','functions','dictionaries'] as const)workspace.value[name]??=[] as any;sessions.value=s.sessions;events.value=s.events||[];lastId.value=events.value.at(-1)?.id||0;await Promise.resolve();initializing=false;dirty.value=false}
async function save(silent=false){await api('Save',JSON.parse(JSON.stringify(workspace.value)));dirty.value=false;if(!silent)notify('工作区已保存')}
async function saveButton(){await action('save',()=>save())}
function retainEvents(items:Event[]){let size=0;let start=items.length;while(start>0&&items.length-start<500){const e=items[start-1]!;const next=2*((e.raw?.length||0)+(e.text?.length||0)+(e.hex?.length||0)+(e.base64?.length||0));if(start<items.length&&size+next>16*1024*1024)break;size+=next;start--}return items.slice(start)}
async function refresh(){if(polling)return;polling=true;try{const s=await api<State>('Status',lastId.value);sessions.value=s.sessions;if(s.events?.length){events.value=retainEvents([...events.value,...s.events]);lastId.value=s.events.at(-1)!.id}}catch{/* surfaced on explicit actions; avoid repeating offline toasts */}finally{polling=false}}
async function connect(){if(!service.value)return;const id=service.value.id;await action('connect',async()=>{await save(true);await api('Connect',id);notify('已建立 TCP 连接');await refresh()})}
async function disconnect(){if(!service.value)return;await action('disconnect',async()=>{await api('Disconnect',service.value!.id);await refresh()})}
async function send(){if(!current.value||!state.value?.connected)return;await action('send',async()=>{await save(true);await api('Send',JSON.parse(JSON.stringify(current.value)));bottomTab.value='messages';selectedEventId.value=null;await refresh();notify('报文已发送')})}
async function addRequest(id?:string){const s=workspace.value.services.find(x=>x.id===(id||service.value?.id));if(!s){editService('tcp');return};if(s.protocol==='fix'){await action('new-message',async()=>{await getDictionary(s.dictionaryId);requestServiceId.value=s.id;const d=dictionaries[s.dictionaryId];requestMessageType.value=d?.messages.find(m=>m.type==='A')?.type||d?.messages[0]?.type||'';requestModal.value=true});return};const r:Request={id:uid(),serviceId:s.id,name:'新建请求',data:'',encoding:'text',preScript:'',postScript:'',requestFunctionId:'',responseFunctionId:'',messageType:'',values:{},rawMode:false};workspace.value.requests.push(r);expanded[s.id]=true;openRequest(r.id)}
function openServiceTemplates(id:string){const rows=requestsFor(id);const r=rows.find(r=>r.messageType==='A')||rows[0];if(r){openRequest(r.id);tab.value='message'}else{serviceId.value=id;selectedId.value='';page.value='workbench'};expanded[id]=true}
async function createMessage(){await action('create-message',async()=>{await save(true);const r=await api<Request>('CreateMessage',requestServiceId.value,requestMessageType.value);await load();requestModal.value=false;expanded[r.serviceId]=true;openRequest(r.id);tab.value='message';notify('已创建 '+r.name)})}
async function generateMessages(id:string){await action('generate',async()=>{await save(true);const count=await api<number>('GenerateMessages',id);await load();openServiceTemplates(id);notify(count?`已补全 ${count} 个消息模板`:'所有消息类型已有模板，已保留现有内容')})}
function editService(protocol?:'tcp'|'fix'){serviceFunctionEditor.value=false;Object.assign(draft,protocol?newService(protocol):JSON.parse(JSON.stringify(service.value)));serviceModal.value=true}
async function saveService(){await action('service',async()=>{const s=JSON.parse(JSON.stringify(draft)) as Service;const isNew=!workspace.value.services.some(x=>x.id===s.id);if(s.framing==='delimiter')s.delimiter=s.delimiter.replace(/\\n/g,'\n').replace(/\\r/g,'\r').replace(/\\x([0-9a-f]{2})/gi,(_,h)=>String.fromCharCode(parseInt(h,16)));await save(true);const count=await api<number>('SaveService',s);await load();serviceId.value=s.id;selectedId.value='';serviceModal.value=false;expanded[s.id]=true;if(isNew&&s.protocol==='fix')openServiceTemplates(s.id);else if(isNew)await addRequest(s.id);notify(count?`服务已创建，已生成 ${count} 个消息模板`:'服务配置已保存；连接中的配置在重新连接后生效')})}
async function removeService(id=service.value?.id){if(!id)return;await action('delete',async()=>{const next=JSON.parse(JSON.stringify(workspace.value)) as Workspace;next.services=next.services.filter(s=>s.id!==id);next.requests=next.requests.filter(r=>r.serviceId!==id);await api('Disconnect',id);await api('Save',next);workspace.value=next;dirty.value=false;openTabs.value=openTabs.value.filter(tabId=>next.requests.some(r=>r.id===tabId));if(!next.requests.some(r=>r.id===selectedId.value)){selectedId.value=openTabs.value.at(-1)||''}if(serviceId.value===id)serviceId.value=current.value?.serviceId||'';delete expanded[id];await refresh();notify('服务及其消息已删除')})}
async function removeRequest(id=current.value?.id){if(!id)return;await action('delete-message',async()=>{const next=JSON.parse(JSON.stringify(workspace.value)) as Workspace;next.requests=next.requests.filter(r=>r.id!==id);await api('Save',next);workspace.value=next;dirty.value=false;closeTab(id);notify('消息已删除')})}
function duplicate(){if(!current.value)return;const r=JSON.parse(JSON.stringify(current.value));r.id=uid();r.name+=' · 副本';workspace.value.requests.push(r);openRequest(r.id);notify('已创建副本，点击保存以保留')}
async function getDictionary(id:string){if(id&&!dictionaries[id])dictionaries[id]=await api<Dictionary>('Dictionary',id)}
async function readXML(event:globalThis.Event){const file=(event.target as HTMLInputElement).files?.[0];if(!file)return;await action('xml',async()=>{await save(true);const id=await api<string>('ImportProtocol',file.name,await file.text());await load();const s=workspace.value.services.find(s=>s.id===id)!;await getDictionary(s.dictionaryId);openServiceTemplates(id);notify(`导入成功：已创建 ${s.name} 服务和 ${requestsFor(id).length} 个消息模板`)});(event.target as HTMLInputElement).value=''}
async function readJSON(event:globalThis.Event){const file=(event.target as HTMLInputElement).files?.[0];if(!file)return;await action('import',async()=>{await api('Import',await file.text());selectedId.value='';openTabs.value=[];await load();notify('工作区已导入')});(event.target as HTMLInputElement).value=''}
async function exportWorkspace(){await action('export',async()=>{await save(true);download('TcpConnect-workspace.json',await api<string>('Export'));notify('工作区已导出（包含已保存的配置和脚本）')})}
async function removeDictionary(id:string){if(workspace.value.services.some(s=>s.dictionaryId===id)){notify('请先删除或更换使用该字典的服务',true);return};workspace.value.dictionaries=workspace.value.dictionaries.filter(d=>d.id!==id);delete dictionaries[id];await saveButton()}
function addFunction(){const f:CustomFunction={id:uid(),name:'新建函数',kind:functionKind.value,code:functionKind.value==='frame'?'// 返回完整报文的字节数；0 表示继续接收\nconst i = bytes.indexOf(10);\nreturn i < 0 ? 0 : i + 1;':'// data 是 UTF-8 文本，bytes 是原始字节数组\nreturn data;'};workspace.value.functions.push(f);selectedFunction.value=f.id}
async function removeFunction(){if(!activeFunction.value)return;const id=activeFunction.value.id;if(workspace.value.requests.some(r=>r.requestFunctionId===id||r.responseFunctionId===id)||workspace.value.services.some(s=>s.frameFunctionId===id)){notify('请先解除该函数的关联',true);return};workspace.value.functions=workspace.value.functions.filter(f=>f.id!==id);selectedFunction.value='';await saveButton()}
function timerExample(){if(!current.value)return;current.value.postScript=`// 每个连接只启动一次；在下方“定时任务”中可停止\nif (!vars.get("pulseStarted")) {\n  vars.set("pulseStarted", true);\n  timers.setInterval("heartbeat", 30000, () => {\n    socket.send("ping\\n");\n    console.log("heartbeat sent", new Date().toISOString());\n  });\n}\n`;tab.value='post';notify('已插入通用 TCP 定时发送示例；FIX 会话自带心跳，无需重复设置')}
function switchMessage(type:string){if(!current.value)return;current.value.messageType=type;current.value.values=type==='A'?{EncryptMethod:'0',HeartBtInt:String(service.value?.heartbeat||30)}:{};optional.value=false}
function formatTime(t:string){return new Date(t).toLocaleTimeString('zh-CN',{hour12:false})+'.'+String(new Date(t).getMilliseconds()).padStart(3,'0')}
function eventText(e?:Event){if(!e)return '';if(view.value==='hex')return (e.hex||'').match(/.{1,2}/g)?.join(' ')||'';if(view.value==='base64')return e.base64||'';if(view.value==='raw')return e.raw||'';return (e.text||'').replace(/\x01/g,'|')}
async function copyText(text:string){try{await navigator.clipboard.writeText(text);notify('已复制')}catch{notify('无法访问剪贴板，请在编辑器中选择并复制',true)}}
watch(workspace,()=>{if(!initializing)dirty.value=true},{deep:true})
watch(searchQuery,query=>{if(query)for(const {service:s} of filteredServices.value)expanded[s.id]=true;nextTick(()=>{const tree=document.querySelector('.service-tree');if(tree)tree.scrollTop=0})})
watch(()=>service.value?.dictionaryId,id=>{if(id)getDictionary(id).catch(e=>notify(String(e),true))},{immediate:true})
watch(current,()=>{const revision=++previewRevision;clearTimeout(previewTimer);preview.value='';previewError.value='';previewTimer=setTimeout(async()=>{if(!current.value)return;try{const result=await api<string>('Preview',JSON.parse(JSON.stringify(current.value)));if(revision===previewRevision){preview.value=result;previewError.value=''}}catch(e){if(revision===previewRevision){previewError.value=String(e instanceof Error?e.message:e);preview.value=''}}},350)},{deep:true})
watch(functionKind,kind=>{if(activeFunction.value?.kind!==kind)selectedFunction.value=workspace.value.functions.find(f=>f.kind===kind)?.id||''})
onMounted(async()=>{try{await load();const first=workspace.value.requests.find(r=>workspace.value.services.find(s=>s.id===r.serviceId)?.protocol==='fix')||workspace.value.requests[0];if(first)openRequest(first.id);for(const s of workspace.value.services)expanded[s.id]=true;poll=window.setInterval(refresh,650)}catch(e){notify(String(e),true)}finally{loading.value=false}})
onBeforeUnmount(()=>{clearInterval(poll);clearTimeout(toastTimer);clearTimeout(previewTimer)})
</script>

<template>
<n-config-provider :theme-overrides="theme">
  <div class="app-shell">
    <nav class="rail"><div class="brand-icon"><Cable :size="23"/></div><button :class="{active:page==='workbench'}" title="调试工作台" @click="page='workbench'"><Layers3 :size="20"/><span>工作台</span></button><button :class="{active:page==='protocols'}" title="协议字典" @click="page='protocols'"><BookOpen :size="20"/><span>协议</span></button><button :class="{active:page==='functions'}" title="处理函数" @click="page='functions'"><Braces :size="20"/><span>函数</span></button><div class="rail-spacer"/><span class="local-mark">LOCAL</span><div class="rail-avatar">TC</div></nav>
    <aside class="sidebar">
      <header class="sidebar-title"><strong>TcpConnect</strong><span class="version">v1.0</span></header><div class="workspace-caption"><span class="workspace-dot"/>本地工作空间<span class="muted">⌄</span></div>
      <div class="sidebar-search"><n-input v-model:value="search" size="small" placeholder="搜索服务或请求"><template #prefix><Search :size="14"/></template></n-input><n-dropdown :options="[{label:'TCP（Socket）服务',key:'tcp'},{label:'FIX 协议服务',key:'fix'},{label:'导入 FIX XML',key:'xml'}]" @select="k=>k==='xml'?importXML?.click():editService(k)"><n-button size="small" type="primary" title="新建"><Plus :size="18"/></n-button></n-dropdown></div>
      <div class="tree-caption">服务与请求 <span>{{filteredServices.length}}</span></div>
      <div class="service-tree">
        <div v-for="{service:s,requests:visibleRequests} in filteredServices" :key="s.id" class="tree-service">
          <div class="service-tree-row" :class="{chosen:service?.id===s.id}" @click="serviceId=s.id;selectedId='';page='workbench';expanded[s.id]=!expanded[s.id]">
            <ChevronDown v-if="expanded[s.id]" :size="13"/><ChevronRight v-else :size="13"/><Radio v-if="s.protocol==='fix'" :size="15" class="purple"/><Cable v-else :size="15" class="purple"/>
            <span :title="s.name">{{s.name}}</span><i class="connection-dot" :class="{online:sessions[s.id]?.connected}"/>
            <div class="tree-actions" @click.stop>
              <button v-if="s.protocol==='fix'" :title="'补全消息模板 '+s.name" class="tree-add" @click="generateMessages(s.id)"><FileCode2 :size="13"/></button>
              <button title="新增请求" class="tree-add" @click="addRequest(s.id)"><Plus :size="14"/></button>
              <n-popconfirm positive-text="删除" negative-text="取消" @positive-click="removeService(s.id)"><template #trigger><button class="tree-delete" :title="'删除服务 '+s.name"><Trash2 :size="13"/></button></template>删除“{{s.name}}”及其 {{requestsFor(s.id).length}} 条消息？活动连接与定时任务将停止。</n-popconfirm>
            </div>
          </div>
          <div v-if="expanded[s.id]" class="tree-requests">
            <div v-for="r in visibleRequests" :key="r.id" class="tree-request-row" :class="{selected:selectedId===r.id&&page==='workbench'}">
              <button class="tree-request-button" :title="r.name" :class="{selected:selectedId===r.id&&page==='workbench'}" @click="openRequest(r.id)"><span class="protocol-label">{{s.protocol==='fix'?'FIX':'TCP'}}</span><span>{{r.name}}</span></button>
              <n-popconfirm positive-text="删除" negative-text="取消" @positive-click="removeRequest(r.id)"><template #trigger><button class="tree-delete" :title="'删除消息 '+r.name"><Trash2 :size="12"/></button></template>删除消息“{{r.name}}”？
</n-popconfirm>
            </div>
            <button v-if="!requestsFor(s.id).length" class="muted" @click="addRequest(s.id)">＋ 新建请求</button>
          </div>
        </div>
        <div v-if="!filteredServices.length" class="empty-tree">{{searchQuery?'没有匹配的服务或消息':'暂无服务'}}<br/><button v-if="searchQuery" @click="search=''">清除搜索</button><button v-else @click="editService('tcp')">创建 TCP 服务</button></div>
      </div>
      <div class="sidebar-footer"><button @click="importJSON?.click()"><Upload :size="14"/>导入工作区</button><button @click="exportWorkspace"><Download :size="14"/>导出</button><div class="local-note"><Circle :size="7" fill="currentColor"/>数据保存在此设备</div></div>
    </aside>
    <main class="main-shell">
      <header class="app-topbar"><div class="breadcrumb"><span>工作空间</span><ChevronRight :size="12"/><span>{{page==='workbench'?(service?.name||'调试工作台'):page==='protocols'?'协议字典':'处理函数'}}</span></div><div class="topbar-right"><span v-if="dirty" class="unsaved-dot">● 未保存</span><span class="device-badge"><Circle :size="7" fill="currentColor"/>仅本机</span><n-button size="small" quaternary @click="saveButton"><Save :size="14"/>&nbsp;保存工作区</n-button></div></header>
      <n-spin v-if="loading" class="loading-state" size="large"/>
      <template v-else-if="page==='workbench'">
        <div class="request-tabs"><button v-for="id in openTabs" :key="id" :class="{active:selectedId===id}" @click="openRequest(id)"><span class="purple small">{{workspace.services.find(s=>s.id===workspace.requests.find(r=>r.id===id)?.serviceId)?.protocol==='fix'?'FIX':'TCP'}}</span>{{workspace.requests.find(r=>r.id===id)?.name}}<X :size="12" @click.stop="closeTab(id)"/></button><button class="add-tab" title="新建请求" @click="addRequest()"><Plus :size="16"/></button></div>
        <div class="workbench-scroll">
          <div class="workbench-heading"><div><div class="eyebrow">{{service?.protocol==='fix'?'FIX PROTOCOL':'TCP SOCKET'}}</div><div class="request-title"><input v-if="current" v-model="current.name" aria-label="请求名称"/><h2 v-else>{{service?.name||'连接，从这里开始'}}</h2><span class="status-pill" :class="{connected:state?.connected}"><i/>{{state?.loggedOn?'FIX 已登录':state?.connected?'已连接':'未连接'}}</span></div></div><div class="heading-actions"><n-button v-if="service" size="small" @click="editService()"><Settings2 :size="14"/>&nbsp;服务设置</n-button><n-button v-if="current" size="small" @click="duplicate"><Copy :size="14"/>&nbsp;另存用例</n-button><n-button v-if="current" size="small" @click="saveButton"><Save :size="14"/>&nbsp;保存</n-button></div></div>
          <div v-if="service" class="connection-bar"><span class="connection-type">{{service.protocol.toUpperCase()}}</span><span class="connection-address">{{service.host}}<span class="muted">:</span>{{service.port}}</span><span v-if="service.protocol==='fix'" class="session-caption">{{service.sender}} <span>→</span> {{service.target}}</span><div class="connection-actions"><n-button v-if="state?.connected" size="small" @click="disconnect"><Square :size="12"/>&nbsp;断开</n-button><n-button v-else size="small" :loading="busy==='connect'" @click="connect"><PlugZap :size="14"/>&nbsp;连接</n-button><n-button v-if="current" type="primary" :disabled="!state?.connected" :loading="busy==='send'" @click="send"><Play :size="13" fill="currentColor"/>&nbsp;发送报文</n-button></div></div>
          <template v-if="current">
            <div class="editor-tabs"><button :class="{active:tab==='message'}" @click="tab='message'">报文内容</button><button :class="{active:tab==='pre'}" @click="tab='pre'">前置脚本<i v-if="current.preScript"/></button><button :class="{active:tab==='post'}" @click="tab='post'">后置脚本<i v-if="current.postScript"/></button><button :class="{active:tab==='settings'}" @click="tab='settings'">处理设置</button><div class="tab-spacer"/><n-button v-if="tab==='pre'||tab==='post'" size="tiny" quaternary @click="timerExample"><Clock3 :size="12"/>&nbsp;定时发送示例</n-button></div>
            <section v-if="tab==='message'" class="request-editor-card">
              <div class="editor-toolbar"><template v-if="service?.protocol==='fix'"><span class="small muted">消息类型</span><n-select :value="current.messageType" :options="msgOptions" filterable size="small" style="width:290px" @update:value="switchMessage"/><n-tag v-if="currentMessage" size="small" :bordered="false">{{currentMessage.category==='admin'?'会话消息':'业务消息'}}</n-tag><div class="tab-spacer"/><n-checkbox v-model:checked="current.rawMode">原始报文</n-checkbox><n-checkbox v-if="!current.rawMode" v-model:checked="optional">显示可选字段</n-checkbox></template><template v-else><span class="small muted">发送格式</span><n-select v-model:value="current.encoding" size="small" style="width:150px" :options="[{label:'UTF-8 文本',value:'text'},{label:'HEX 十六进制',value:'hex'},{label:'Base64',value:'base64'}]"/><div class="tab-spacer"/><span class="muted small">原始数据 · 不自动添加换行</span></template></div>
              <div v-if="service?.protocol==='fix'&&!current.rawMode" class="fix-form-scroll"><div class="managed-fields"><span>自动维护</span><code>8 · 9 · 35 · 34 · 49 · 52 · 56 · 10</code><span class="muted">序号 {{state?.nextSeq||1}} · UTC 时间 · 长度与校验和</span></div><FixFields v-if="currentMessage" :nodes="currentMessage.nodes" :values="current.values" :show-optional="optional"/><n-empty v-else description="请选择字典中的消息类型" size="small"/></div>
              <CodeEditor v-else v-model="current.data" :key="current.id+'data'"/>
              <div v-if="service?.protocol==='fix'&&!current.rawMode" class="fix-preview"><span>报文预览</span><code :class="{muted:previewError}">{{previewError||preview||'填写字段后显示报文'}}</code></div>
              <div v-if="current.rawMode" class="inline-note">原始模式：不自动维护序号、时间、长度或校验和，适用于异常报文测试。</div>
            </section>
            <section v-else-if="tab==='pre'||tab==='post'" class="request-editor-card"><div class="script-hint"><FileCode2 :size="14"/><span v-if="tab==='pre'">发送前执行 · data / bytes 为当前报文，return 返回新的报文</span><span v-else>每条完整响应后执行 · 使用 console.log 查看日志、socket.send 发送、timers 管理定时器</span><span class="tab-spacer"/><span>JavaScript</span></div><CodeEditor v-if="tab==='pre'" v-model="current.preScript" language="javascript" :key="current.id+'pre'"/><CodeEditor v-else v-model="current.postScript" language="javascript" :key="current.id+'post'"/></section>
            <section v-else class="request-editor-card processing-settings"><div class="settings-label">发送与展示处理</div><n-form label-placement="left" label-width="140"><n-form-item label="请求数据处理函数"><n-select v-model:value="current.requestFunctionId" :options="functionOptions('request')"/></n-form-item><n-form-item label="返回数据处理函数"><n-select v-model:value="current.responseFunctionId" :options="functionOptions('response')"/></n-form-item></n-form><div class="inline-note">函数修改后需重新连接。接收分帧规则在“服务设置”中配置，原始字节始终保留。</div><n-button size="small" @click="page='functions'">管理三类自定义函数 <ArrowUpRight :size="14"/></n-button></section>
          </template>
          <div v-else class="welcome-card"><div class="welcome-icon"><Cable :size="30"/></div><h2>每一次连接，都清晰可见</h2><p>打开左侧请求，或新建请求开始调试。</p><div><n-button type="primary" @click="addRequest()">＋ 新建请求</n-button><n-button v-if="service?.protocol==='fix'" @click="importXML?.click()">导入 FIX XML</n-button></div></div>
          <section class="response-panel"><div class="editor-tabs response-tabs"><button :class="{active:bottomTab==='messages'}" @click="bottomTab='messages'"><Activity :size="14"/>收发记录<span class="count-badge">{{messages.length}}</span></button><button :class="{active:bottomTab==='console'}" @click="bottomTab='console'"><Terminal :size="14"/>脚本与事件<span class="count-badge">{{logs.length}}</span><i v-if="logs.some(e=>e.kind==='error')" class="error-dot"/></button><button :class="{active:bottomTab==='tasks'}" @click="bottomTab='tasks'"><Clock3 :size="14"/>定时任务<span class="count-badge">{{state?.tasks?.length||0}}</span></button><div class="tab-spacer"/><span v-if="service?.protocol==='fix'&&state?.connected" class="small muted">发送序号 {{state.nextSeq}} / 接收期望 {{state.expectedSeq}}</span><n-button size="tiny" quaternary @click="api('ClearEvents').then(()=>{events=[];selectedEventId=null})"><Trash2 :size="13"/>&nbsp;清空</n-button></div>
            <div v-if="bottomTab==='messages'" class="response-body"><div v-if="messages.length" class="message-list"><button class="follow-latest" @click="selectedEventId=null">{{selectedEventId===null?'● 正在跟随最新':'查看最新记录 ↓'}}</button><button v-for="e in [...messages].reverse()" :key="e.id" class="message-entry" :class="{selected:selectedEvent?.id===e.id}" @click="selectedEventId=e.id"><div class="message-entry-top"><ArrowUpRight v-if="e.direction==='send'" :size="15" class="send-icon"/><ArrowDownLeft v-else :size="15" class="receive-icon"/><strong>{{e.direction==='send'?'发送':'接收'}}</strong><time>{{formatTime(e.time)}}</time><span>{{e.size}} B</span></div><code>{{(e.raw||'').replace(/\x01/g,'|').slice(0,90)}}</code></button></div><div class="response-detail"><template v-if="selectedEvent"><div class="response-toolbar"><div class="segmented"><button v-for="v in [{id:'text',label:'处理后数据'},{id:'raw',label:'原始文本'},{id:'hex',label:'HEX'},{id:'base64',label:'Base64'},...(service?.protocol==='fix'?[{id:'fields',label:'FIX 字段'}]:[])]" :key="v.id" :class="{active:view===v.id}" @click="view=v.id">{{v.label}}</button></div><n-button size="tiny" quaternary @click="copyText(eventText(selectedEvent))"><Copy :size="13"/></n-button></div><div v-if="view==='fields'" class="decoded-table"><table><thead><tr><th>Tag</th><th>字段 / 分组</th><th>值</th><th>说明</th></tr></thead><tbody><tr v-for="(row,i) in decoded" :key="i"><td>{{row.tag}}</td><td><small v-if="row.path">{{row.path}}</small>{{row.name}}</td><td>{{row.name==='Password'?'••••••':row.value}}</td><td>{{row.description}}</td></tr></tbody></table></div><pre v-else class="response-text">{{eventText(selectedEvent)}}</pre></template><div v-else class="response-empty"><Activity :size="30"/><strong>等待数据到达</strong><span>连接服务并发送报文，响应与主动推送将在这里展示</span></div></div></div>
            <div v-else-if="bottomTab==='console'" class="console-list"><div v-if="!logs.length" class="muted">脚本日志、异常和连接事件将在这里显示</div><div v-for="e in logs" :key="e.id" class="console-line" :class="e.kind"><time>{{formatTime(e.time)}}</time><span class="log-kind">{{e.kind.toUpperCase()}}</span><pre>{{e.text}}</pre></div></div>
            <div v-else class="task-list"><n-empty v-if="!state?.tasks?.length" size="small" description="当前连接没有脚本定时任务"/><div v-for="name in state?.tasks" :key="name" class="task-row"><Clock3 :size="18" class="purple"/><div><strong>{{name}}</strong><small>运行在当前 TCP 连接 · 断开时自动停止</small></div><n-button size="small" @click="api('StopTask',service!.id,name).then(refresh)">停止任务</n-button></div><div v-if="service?.protocol==='fix'" class="inline-note">FIX 会话心跳由协议模块自动管理，登录成功后生效。</div></div>
          </section>
          <div v-if="current" class="request-footer"><span>修改会在发送前保存</span><n-popconfirm @positive-click="removeRequest()"><template #trigger><button class="danger-link">删除此请求</button></template>删除此请求？</n-popconfirm></div>
        </div>
      </template>
      <section v-else-if="page==='protocols'" class="management-page"><div class="page-heading"><div><div class="eyebrow">PROTOCOL LIBRARY</div><h1>协议字典</h1><p>导入 FIX XML，自动创建服务与全部消息模板。</p></div><n-button type="primary" :loading="busy==='xml'" @click="importXML?.click()"><Upload :size="15"/>&nbsp;导入 FIX XML</n-button></div><div class="protocol-banner"><div class="protocol-banner-icon"><Radio :size="28"/></div><div><strong>通用 TCP，一套可扩展的协议工作台</strong><p>字典在运行时解析。字段、枚举、组件和重复组由导入内容决定，支持业务自定义消息。</p></div><n-tag :bordered="false" type="success">FIX 4.4</n-tag></div><div class="dictionary-grid"><article v-for="d in workspace.dictionaries" :key="d.id" class="dictionary-card"><div class="dictionary-card-title"><FileCode2 :size="25" class="purple"/><strong>{{d.name}}</strong></div><div class="dictionary-stats" @vue:mounted="getDictionary(d.id)"><span><strong>{{dictionaries[d.id]?.messages.length??'—'}}</strong>消息</span><span><strong>{{dictionaries[d.id]?.fields.length??'—'}}</strong>字段</span><span><strong>{{dictionaries[d.id]?.componentCount??'—'}}</strong>组件</span></div><div class="dictionary-card-footer"><span class="muted small">{{dictionaries[d.id]?.version||'QuickFIX XML'}}</span><n-button size="small" secondary type="primary" @click="editService('fix');draft.dictionaryId=d.id">创建 FIX 服务</n-button><n-popconfirm @positive-click="removeDictionary(d.id)"><template #trigger><n-button size="small" quaternary title="删除字典"><Trash2 :size="14"/></n-button></template>删除此字典？</n-popconfirm></div><details class="dictionary-messages"><summary>浏览消息定义</summary><div v-for="m in dictionaries[d.id]?.messages" :key="m.type"><code>{{m.type}}</code>{{m.name}}<small>{{m.category}}</small></div></details></article></div><div class="info-card"><BookOpen :size="18"/><div><strong>字典决定结构，会话维护连接</strong><p>XML 提供类型、枚举、必填、组件及重复组。FIX 会话自动维护 UTC 时间、长度、校验和、心跳和消息序号。业务条件与默认值可通过脚本或用例补充。</p></div></div></section>
      <section v-else class="management-page"><div class="page-heading"><div><div class="eyebrow">SCRIPT FUNCTIONS</div><h1>自定义函数</h1><p>转换发送与返回数据，或定义完整报文的接收边界。</p></div><div class="heading-actions"><template v-if="serviceFunctionEditor"><n-button @click="returnToService()">返回服务设置</n-button><n-button type="primary" :disabled="activeFunction?.kind!=='frame'" @click="returnToService(true)">绑定并返回服务设置</n-button></template><n-button type="primary" @click="addFunction"><Plus :size="16"/>&nbsp;新建函数</n-button></div></div><div class="function-kind-tabs"><button v-for="k in [{id:'request',label:'请求数据处理'},{id:'response',label:'返回数据处理'},{id:'frame',label:'接收完成判断'}]" :key="k.id" :class="{active:functionKind===k.id}" @click="functionKind=k.id as any;selectedFunction=workspace.functions.find(f=>f.kind===k.id)?.id||''">{{k.label}}</button></div><div class="function-workspace"><div class="function-list"><button v-for="f in workspace.functions.filter(f=>f.kind===functionKind)" :key="f.id" :class="{active:selectedFunction===f.id}" @click="selectedFunction=f.id"><Braces :size="15"/>{{f.name}}</button><button class="new-function" @click="addFunction">＋ 新建函数</button></div><div v-if="activeFunction" class="function-editor"><div class="function-editor-header"><n-input v-model:value="activeFunction.name" placeholder="函数名称"/><n-button type="primary" size="small" @click="saveButton">保存函数</n-button><n-popconfirm @positive-click="removeFunction"><template #trigger><n-button size="small" quaternary><Trash2 :size="15"/></n-button></template>删除该函数？</n-popconfirm></div><div class="script-hint">{{functionKind==='frame'?'返回帧字节数；0 表示未完成。必须保留后续粘包与残包。':'data 为 UTF-8 文本，bytes 为原始字节；返回字符串或 Uint8Array。'}}</div><CodeEditor v-model="activeFunction.code" language="javascript" :key="activeFunction.id"/></div><div v-else class="function-empty"><Braces :size="32"/><strong>让每份数据，都按你的规则流动</strong><span>选择或新建一个函数，保存后在请求或服务设置中关联。</span></div></div><div class="info-card"><Terminal :size="18"/><div><strong>脚本 API</strong><p><code>socket.send(data)</code> 当前连接发送 · <code>vars.get / set</code> 会话变量 · <code>timers.setInterval(name, ms, fn)</code> 定时发送 · <code>console.log</code> 窗口日志。前后置脚本在请求工作区编辑，函数更新后重新连接。</p></div></div></section>
      <footer class="statusbar"><span><Circle :size="6" fill="currentColor"/>本地工作台</span><span>{{workspace.services.length}} 个服务 · {{Object.values(sessions).filter(s=>s.connected).length}} 个连接</span><div class="tab-spacer"/><span>UTF-8</span><span>TCP / FIX 4.4</span></footer>
    </main>
  </div>
  <n-modal v-model:show="serviceModal" preset="card" :title="workspace.services.some(s=>s.id===draft.id)?'编辑服务':'新建 '+draft.protocol.toUpperCase()+' 服务'" style="width:650px;max-height:90vh;overflow:auto" :bordered="false"><n-form label-placement="left" label-width="110"><n-form-item label="服务名称" required><n-input v-model:value="draft.name"/></n-form-item><div class="form-two-cols"><n-form-item label="主机地址" required><n-input v-model:value="draft.host" placeholder="127.0.0.1"/></n-form-item><n-form-item label="端口" label-width="55" required><n-input-number v-model:value="draft.port" :min="1" :max="65535"/></n-form-item></div><n-form-item label="连接超时 (ms)"><n-input-number v-model:value="draft.timeoutMs" :min="100" :max="30000" :step="1000"/></n-form-item><template v-if="draft.protocol==='fix'"><n-form-item label="协议字典" required><n-select v-model:value="draft.dictionaryId" :options="workspace.dictionaries.map(d=>({label:d.name,value:d.id}))"/><n-button quaternary @click="serviceModal=false;importXML?.click()">导入</n-button></n-form-item><n-form-item label="SenderCompID"><n-input v-model:value="draft.sender"/></n-form-item><n-form-item label="TargetCompID"><n-input v-model:value="draft.target"/></n-form-item><n-form-item label="心跳间隔 (秒)"><n-input-number v-model:value="draft.heartbeat" :min="1" :max="3600"/></n-form-item><n-form-item label="连接后自动登录"><n-switch v-model:value="draft.autoLogon"/></n-form-item><n-form-item label="登录重置序号"><n-switch v-model:value="draft.resetOnLogon"/></n-form-item><template v-if="draft.autoLogon"><n-form-item label="Username"><n-input v-model:value="draft.username"/></n-form-item><n-form-item label="Password"><n-input v-model:value="draft.password" type="password" show-password-on="click"/></n-form-item></template><div class="inline-note">自动登录使用服务中的凭据；手动登录使用 Logon 表单。凭据随工作区在本机保存，导出时一并包含。每次新连接从序号 1 开始。</div></template><template v-else>
    <n-form-item label="接收完成规则" required><n-select v-model:value="framingRule" class="receive-rule-select" :options="framingOptions" filterable placeholder="选择内置规则或自定义函数"/></n-form-item>
    <n-form-item v-if="draft.framing==='delimiter'" label="分隔符"><n-input v-model:value="draft.delimiter" placeholder="支持 \n、\r、\x01"/></n-form-item>
    <n-form-item v-if="draft.framing==='fixed'||draft.framing==='length'" :label="draft.framing==='fixed'?'报文字节数':'长度头字节数'"><n-input-number v-model:value="draft.frameLength" :min="1" :max="draft.framing==='length'?10:4194304"/></n-form-item>
    <div v-if="draft.framing==='custom'" class="inline-note">已绑定：{{boundFrameFunction?.name||'请选择有效的接收判断函数'}}。函数返回完整报文的字节数，0 表示继续接收；粘包中的剩余字节会继续判断。</div>
    <div v-else-if="!frameFunctions.length" class="inline-note">尚无接收判断函数，可先在函数管理中创建。</div>
    <n-button size="small" secondary @click="manageFrameFunctions">{{draft.framing==='custom'?'编辑或更换绑定函数':'管理接收判断函数'}} <ArrowUpRight :size="14"/></n-button>
    <div class="inline-note">仅可绑定“接收完成判断”类函数；保存服务后重新连接生效。</div>
  </template></n-form><template #footer><div class="modal-footer"><n-popconfirm v-if="workspace.services.some(s=>s.id===draft.id)" @positive-click="serviceModal=false;removeService(draft.id)"><template #trigger><n-button type="error" quaternary>删除服务</n-button></template>断开连接并删除服务及其请求？</n-popconfirm><div class="tab-spacer"/><n-button @click="serviceModal=false">取消</n-button><n-button type="primary" :loading="busy==='service'" @click="saveService">保存服务</n-button></div></template></n-modal>
  <n-modal v-model:show="requestModal" preset="card" title="新建 FIX 消息" style="width:520px" :bordered="false">
    <n-form label-placement="left" label-width="90"><n-form-item label="消息类型" required><n-select v-model:value="requestMessageType" filterable :options="requestDictionary?.messages.map(m=>({label:m.name+' ('+m.type+')',value:m.type}))||[]"/></n-form-item></n-form>
    <p class="muted small">选择字典中的消息，自动创建对应的字段、枚举、组件与重复组表单。</p>
    <template #footer><div class="modal-footer"><div class="tab-spacer"/><n-button @click="requestModal=false">取消</n-button><n-button type="primary" :disabled="!requestMessageType" :loading="busy==='create-message'" @click="createMessage">创建消息</n-button></div></template>
  </n-modal>
  <input ref="importXML" type="file" accept=".xml" hidden @change="readXML"/><input ref="importJSON" type="file" accept=".json" hidden @change="readJSON"/>
  <div v-if="toast" class="toast" :class="{error:toastError}"><X v-if="toastError" :size="17"/><Check v-else :size="17"/><span>{{toast}}</span><button @click="toast=''"><X :size="13"/></button></div>
</n-config-provider>
</template>
